// Binary-search lookup. Returns kStarsCount when not found —
// caller compares against that sentinel rather than -1 so the
// return type stays unsigned.
inline constexpr uint16_t find_by_hip(uint32_t hip) {
  uint16_t lo = 0, hi = kStarsCount;
  while (lo < hi) {
    const uint16_t mid = static_cast<uint16_t>((lo + hi) / 2);
    const uint32_t h = kStars[mid].hip;
    if      (h < hip) lo = static_cast<uint16_t>(mid + 1);
    else if (h > hip) hi = mid;
    else              return mid;
  }
  return kStarsCount;
}

